package dev.thedocruby.resounding.debug.math;

/**
 * Fixed depth-to-color mapping for octree octant wireframes (sizes 16/8/4/2/1).
 */
public final class DepthColor {

    private DepthColor() {}

    public static int colorForSize(int size) {
        return switch (size) {
            case 16 -> 0xFFFF0000;
            case 8 -> 0xFF00FF00;
            case 4 -> 0xFF0000FF;
            case 2 -> 0xFFFFFF00;
            case 1 -> 0xFFFF00FF;
            default -> throw new IllegalArgumentException("unexpected octree node size: " + size);
        };
    }
}

package dev.thedocruby.resounding.debug.math;

import java.util.ArrayList;
import java.util.List;

/**
 * Bounded drop-oldest-on-overflow queue backing live/capture ray caps.
 */
public final class RingBuffer<T> {

    private final int capacity;
    private final Object[] buffer;
    private int head;
    private int size;

    public RingBuffer(int capacity) {
        this.capacity = capacity;
        this.buffer = new Object[capacity];
    }

    public void offer(T element) {
        if (capacity == 0) {
            return;
        }
        if (size < capacity) {
            buffer[(head + size) % capacity] = element;
            size++;
        } else {
            buffer[head] = element;
            head = (head + 1) % capacity;
        }
    }

    @SuppressWarnings("unchecked")
    public List<T> asList() {
        List<T> result = new ArrayList<>(size);
        for (int i = 0; i < size; i++) {
            result.add((T) buffer[(head + i) % capacity]);
        }
        return List.copyOf(result);
    }

    public int size() {
        return size;
    }

    public int capacity() {
        return capacity;
    }
}

package dev.thedocruby.resounding.debug;

import dev.thedocruby.resounding.raycast.Branch;
import net.minecraft.util.math.Box;

import java.util.ArrayList;
import java.util.List;

/**
 * Walks a section octree and emits one axis-aligned box per node for wireframe rendering.
 */
public final class OctreeOverlay {

    private OctreeOverlay() {}

    public static List<Box> collectOctants(Branch root) {
        List<Box> boxes = new ArrayList<>();
        collectOctants(root, boxes);
        return boxes;
    }

    private static void collectOctants(Branch node, List<Box> boxes) {
        int x = node.start.getX();
        int y = node.start.getY();
        int z = node.start.getZ();
        int size = node.size;
        boxes.add(new Box(x, y, z, x + size, y + size, z + size));

        if (!node.leaves.isEmpty()) {
            for (Branch child : node.leaves.values()) {
                collectOctants(child, boxes);
            }
        }
    }
}

package dev.thedocruby.resounding.debug.math;

/**
 * Plain-double 3D line segment for closest-distance queries (no Minecraft types).
 */
public record Segment3(double ax, double ay, double az, double bx, double by, double bz) {

    private static final double EPS = 1e-12;

    public double closestDistanceTo(Segment3 other) {
        double uX = bx - ax;
        double uY = by - ay;
        double uZ = bz - az;
        double vX = other.bx - other.ax;
        double vY = other.by - other.ay;
        double vZ = other.bz - other.az;
        double wX = ax - other.ax;
        double wY = ay - other.ay;
        double wZ = az - other.az;

        double a = dot(uX, uY, uZ, uX, uY, uZ);
        double b = dot(uX, uY, uZ, vX, vY, vZ);
        double c = dot(vX, vY, vZ, vX, vY, vZ);
        double d = dot(uX, uY, uZ, wX, wY, wZ);
        double e = dot(vX, vY, vZ, wX, wY, wZ);

        if (a <= EPS && c <= EPS) {
            return distance(ax, ay, az, other.ax, other.ay, other.az);
        }
        if (a <= EPS) {
            return other.closestDistanceToPoint(ax, ay, az);
        }
        if (c <= EPS) {
            return closestDistanceToPoint(other.ax, other.ay, other.az);
        }

        double denom = a * c - b * b;
        double sc;
        double sN;
        double sD = denom;
        double tc;
        double tN;
        double tD = denom;

        if (denom < EPS) {
            sN = 0.0;
            sD = 1.0;
            tN = e;
            tD = c;
        } else {
            sN = b * e - c * d;
            tN = a * e - b * d;
            if (sN < 0.0) {
                sN = 0.0;
                tN = e;
                tD = c;
            } else if (sN > sD) {
                sN = sD;
                tN = e + b;
                tD = c;
            }
        }

        if (tN < 0.0) {
            tN = 0.0;
            if (-d < 0.0) {
                sN = 0.0;
            } else if (-d > a) {
                sN = sD;
            } else {
                sN = -d;
                sD = a;
            }
        } else if (tN > tD) {
            tN = tD;
            if (-d + b < 0.0) {
                sN = 0.0;
            } else if (-d + b > a) {
                sN = sD;
            } else {
                sN = -d + b;
                sD = a;
            }
        }

        sc = Math.abs(sN) < EPS ? 0.0 : sN / sD;
        tc = Math.abs(tN) < EPS ? 0.0 : tN / tD;

        double dX = wX + sc * uX - tc * vX;
        double dY = wY + sc * uY - tc * vY;
        double dZ = wZ + sc * uZ - tc * vZ;
        return Math.sqrt(dX * dX + dY * dY + dZ * dZ);
    }

    public double closestDistanceToPoint(double x, double y, double z) {
        double uX = bx - ax;
        double uY = by - ay;
        double uZ = bz - az;
        double lenSq = dot(uX, uY, uZ, uX, uY, uZ);
        if (lenSq <= EPS) {
            return distance(ax, ay, az, x, y, z);
        }

        double t = dot(x - ax, y - ay, z - az, uX, uY, uZ) / lenSq;
        t = Math.max(0.0, Math.min(1.0, t));

        double closestX = ax + t * uX;
        double closestY = ay + t * uY;
        double closestZ = az + t * uZ;
        return distance(closestX, closestY, closestZ, x, y, z);
    }

    private static double dot(double ax, double ay, double az, double bx, double by, double bz) {
        return ax * bx + ay * by + az * bz;
    }

    private static double distance(double ax, double ay, double az, double bx, double by, double bz) {
        double dx = ax - bx;
        double dy = ay - by;
        double dz = az - bz;
        return Math.sqrt(dx * dx + dy * dy + dz * dz);
    }
}
